<script lang="ts">
  import {untrack,onDestroy} from 'svelte';
  import {ApiError} from '../api/client';
  import {operationUid} from '../api/operation';
  import {loadWorkflowStatus,workflowAction,loadWorkflowHistory,type WorkflowStatus,type AvailableAction,type WorkflowHistory,type WorkflowOperation} from '../api/workflows';
  let {moduleUid,recordUid,recordRevision,liveRevision=0,onReload,onChanged,onSnapshot}:{moduleUid:string;recordUid:string;recordRevision:number;liveRevision?:number;onReload:()=>Promise<void>;onChanged:()=>Promise<void>;onSnapshot:(uid:string)=>void}=$props();
  let status=$state<WorkflowStatus|null>(null);let loading=$state(false);let busy=$state(false);let error=$state('');let notice=$state('');let selected=$state<AvailableAction|null>(null);let note=$state('');
  let pending=$state<WorkflowOperation|null>(null);let history=$state<WorkflowHistory|null>(null);let historyOpen=$state(false);let historyBusy=$state(false);let historyError=$state('');
  let controller:AbortController|undefined;let historyController:AbortController|undefined;let dead=false;
  const stale=$derived(status?.record_revision!==recordRevision);
  $effect(()=>{moduleUid;recordUid;recordRevision;liveRevision;untrack(()=>void reload());});
  onDestroy(()=>{dead=true;controller?.abort();historyController?.abort();});
  async function reload(){controller?.abort();const request=new AbortController();controller=request;loading=true;try{const value=await loadWorkflowStatus(moduleUid,recordUid,request.signal);if(request.signal.aborted||dead)return;const changed=status&&(value.configuration_revision!==status.configuration_revision||value.workflow_revision!==status.workflow_revision||value.record_revision!==status.record_revision);status=value;if(!pending){error='';if(changed){selected=null;notice='The process or saved record changed. Review the latest state before choosing an action.';}}if(historyOpen)void showHistory();}catch(reason){if(!request.signal.aborted&&!dead)error=reason instanceof Error?reason.message:String(reason);}finally{if(controller===request)loading=false;}}
  async function act(){if(busy||!status||!selected||stale&&!pending)return;busy=true;error='';notice='';
    if(!pending)pending={operation_uid:operationUid(),action:selected.key,configuration_revision:status.configuration_revision,workflow_revision:status.workflow_revision!,record_revision:status.record_revision!,note};
    try{const result=await workflowAction(moduleUid,recordUid,$state.snapshot(pending));if(dead)return;pending=null;status=result.status;selected=null;note='';notice=result.replayed?'MX confirmed the previously submitted action. It was not applied twice.':'Action saved to MX with a record snapshot.';try{await onChanged();}catch{notice+=' The record list could not refresh; use Refresh when the connection recovers.';}if(historyOpen)await showHistory();}
    catch(reason){if(dead)return;if(reason instanceof ApiError&&[400,403,404,409].includes(reason.status))pending=null;error=reason instanceof Error?reason.message:String(reason);}
    finally{busy=false;}
  }
  async function showHistory(before?:number){historyController?.abort();const request=new AbortController();historyController=request;historyOpen=true;historyBusy=true;historyError='';try{const value=await loadWorkflowHistory(moduleUid,recordUid,before,request.signal);if(!request.signal.aborted)history=value;}catch(reason){if(!request.signal.aborted)historyError=reason instanceof Error?reason.message:String(reason);}finally{if(historyController===request)historyBusy=false;}}
</script>
{#if status?.enabled||status?.has_history||error}
<section class="record-process" aria-label="Record process" aria-busy={loading||busy}>
  <header><div><small>{status?.name||'Process status'}</small>{#if status?.enabled||status?.has_history}<strong>{status.enabled?'':'Process disabled · '}{status.state_name}</strong>{/if}</div><div class="button-row"><button class="button small" type="button" disabled={loading||busy} onclick={reload}>Refresh process</button>{#if status?.enabled||status?.has_history}<button class="button small" type="button" disabled={busy} aria-expanded={historyOpen} onclick={()=>{if(historyOpen)historyOpen=false;else void showHistory();}}>Decision history</button>{/if}</div></header>
  {#if status?.restarted}<p class="notice" role="status">This record changed after its last action. Its earlier decision does not approve the current values; the process must start again.</p>{:else if status?.changed_since_action}<p class="muted small">The record changed after its last action. Earlier decisions refer to their saved revision, not these latest values.</p>{/if}
  {#if status?.enabled&&stale}<p class="notice" role="status">There are newer saved values. Review them before taking action. <button class="button small" type="button" disabled={busy} onclick={onReload}>Load latest record</button></p>{/if}
  {#if error}<div class="notice error" role="alert">{error}{#if pending}<p>The result is not yet confirmed. Retrying checks the same operation; it cannot apply twice.</p><button class="button small" type="button" disabled={busy} onclick={act}>Check and retry action</button>{:else}<button class="button small" type="button" disabled={loading||busy} onclick={reload}>Reload process</button>{/if}</div>{/if}
  {#if notice}<p role="status" class="notice">{notice}</p>{/if}
  {#if status?.enabled&&!selected}<div class="process-actions">{#each status.actions||[] as action}<div><button class="button" type="button" disabled={busy||loading||stale||!!pending||!!action.blocked_reason||action.missing_fields.length>0} onclick={()=>{selected=action;note='';error='';notice='';}}>{action.name}</button>{#if action.blocked_reason}<small>{action.blocked_reason}</small>{/if}{#if action.missing_fields.length}<small>Complete first: {action.missing_fields.join(', ')}.</small>{/if}</div>{/each}</div>{#if !status.actions?.length}<p class="muted small">No actions are available to your account at this stage.</p>{/if}{/if}
  {#if selected}<div class="action-confirmation"><strong>{selected.name} → {selected.to_name}</strong><p>Applies to the saved record revision {status?.record_revision}. The action and its snapshot are saved together.</p><label>Action note{selected.note_required?' (required)':' (optional)'}<textarea bind:value={note} rows="2" maxlength="2000" disabled={busy||!!pending}></textarea></label><small>Visible to everyone who can view this record.</small><div class="button-row"><button class="button" type="button" disabled={busy||!!pending} onclick={()=>selected=null}>Cancel action</button><button class="button primary" type="button" disabled={busy||loading||stale||!!pending||selected.note_required&&!note.trim()} onclick={act}>{busy?'Confirming with MX…':`Confirm ${selected.name.toLowerCase()}`}</button></div></div>{/if}
  {#if historyOpen}<section class="decision-history" aria-label="Decision history"><h3>Decision history</h3>{#if historyError}<p class="notice error" role="alert">{historyError}<button type="button" class="button small" onclick={()=>showHistory()}>Retry history</button></p>{/if}{#if historyBusy}<p role="status">Loading decisions…</p>{/if}{#each history?.items||[] as event}<article><strong>{event.action_name} · {event.from_name} → {event.to_name}</strong><small>{event.actor_name} · {new Date(event.created_at).toLocaleString()} · Record revision {event.record_revision}</small>{#if event.note}<p>{event.note}</p>{/if}<button class="button small" type="button" onclick={()=>onSnapshot(event.snapshot_uid)}>View decision snapshot</button></article>{/each}{#if history&&!history.items.length}<p class="muted">No actions have been taken on this record yet.</p>{/if}<div class="button-row"><button class="button small" type="button" disabled={historyBusy} onclick={()=>showHistory()}>Latest decisions</button>{#if history?.has_next}<button class="button small" type="button" disabled={historyBusy} onclick={()=>showHistory(history?.next_cursor||undefined)}>Older decisions</button>{/if}</div></section>{/if}
</section>{/if}
<style>
  .record-process{margin:0 1rem 1rem;padding:1rem;border:1px solid var(--line);border-radius:.6rem;min-width:0}header{display:flex;gap:.75rem;justify-content:space-between;align-items:center;flex-wrap:wrap}header>div:first-child{display:grid;gap:.2rem}small{font-size:.875rem;color:var(--muted);line-height:1.5;overflow-wrap:anywhere}.process-actions{display:flex;gap:.75rem;flex-wrap:wrap;margin-top:.8rem}.process-actions>div{display:grid;gap:.3rem;max-width:24rem}.action-confirmation{display:grid;gap:.65rem;margin-top:1rem;padding-top:1rem;border-top:1px solid var(--line)}.action-confirmation p{margin:0;color:var(--muted)}label{display:grid;gap:.4rem}textarea{width:100%;resize:vertical;min-height:4rem}.decision-history{margin-top:1rem;border-top:1px solid var(--line)}h3{font-size:1rem}.decision-history article{padding:.85rem 0;border-bottom:1px solid var(--line);display:grid;gap:.4rem}.decision-history p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.decision-history article button{justify-self:start}.decision-history>.button-row{margin-top:.75rem}.notice{margin:.75rem 0}.button-row{display:flex;flex-wrap:wrap;gap:.5rem}
</style>
